// hive-managed: session events
// Generated by Hive; `hive update` rewrites this file and `hive plan remove` deletes it.
// It reports OpenCode session events to the Hive viewer by running
// `hive hook opencode <event>` detached, so OpenCode never waits for it and the
// hook cannot print into the session. It reads nothing but the event itself.
import { spawn } from "node:child_process"

const EXECUTABLE = __HIVE_EXECUTABLE__
const MAX_TODOS = 50
const MAX_TRACKED_SESSIONS = 50

function text(value) {
  return typeof value === "string" && value.length > 0 ? value : ""
}

function sessionOf(event) {
  return (
    text(event?.data?.sessionID) ||
    text(event?.properties?.info?.id) ||
    text(event?.properties?.sessionID) ||
    text(event?.sessionID) ||
    text(event?.id)
  )
}

// whenOf is the event's own time when it has one, else the moment the plugin
// handles it. The hook never reads its clock: a resend of the same event must
// carry the same time.
function whenOf(event) {
  for (const value of [event?.time, event?.timestamp, event?.data?.time, event?.data?.timestamp]) {
    if (typeof value === "number" && Number.isFinite(value)) return new Date(value).toISOString()
    if (typeof value === "string" && !Number.isNaN(Date.parse(value))) return new Date(value).toISOString()
  }
  return new Date().toISOString()
}

function report(name, sessionID, directory, occurredAt, extra) {
  if (!sessionID) return
  try {
    const body = JSON.stringify({ session_id: sessionID, directory: directory || "", occurred_at: occurredAt, ...extra })
    const child = spawn(EXECUTABLE, ["hook", "opencode", name], {
      stdio: ["pipe", "ignore", "ignore"],
      detached: true,
      windowsHide: true,
    })
    child.on("error", () => {})
    child.stdin.on("error", () => {})
    child.stdin.end(body)
    child.unref()
  } catch {
    // A hook must never disturb the host.
  }
}

export default {
  id: "hive.session-events",
  async setup(ctx) {
    const base = text(ctx?.location?.directory) || text(ctx?.directory)
    const directories = new Map()
    const remember = (sessionID, directory) => {
      directories.delete(sessionID)
      directories.set(sessionID, directory)
      while (directories.size > MAX_TRACKED_SESSIONS) directories.delete(directories.keys().next().value)
    }
    const directoryOf = (sessionID) => (sessionID && directories.get(sessionID)) || base

    await ctx.tool.hook("execute.after", (event) => {
      try {
        if (event?.tool !== "todowrite") return
        const list = event?.input?.todos ?? event?.args?.todos
        if (!Array.isArray(list)) return
        const todos = list.slice(0, MAX_TODOS).map((todo) => ({ content: todo?.content, status: todo?.status }))
        const sessionID = text(event?.sessionID)
        report("todowrite", sessionID, directoryOf(sessionID), whenOf(event), { todos })
      } catch {
        // Ignored: see report.
      }
    })

    const controller = new AbortController()
    ;(async () => {
      try {
        for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
          const type = text(event?.type)
          if (type !== "session.created" && type !== "session.deleted" && !type.startsWith("session.execution.")) continue
          const sessionID = sessionOf(event)
          const directory = text(event?.location?.directory) || text(event?.data?.location?.directory)
          if (sessionID && directory) remember(sessionID, directory)
          report(type, sessionID, directoryOf(sessionID), whenOf(event), {})
          if (type === "session.deleted" && sessionID) directories.delete(sessionID)
        }
      } catch {
        // The subscription ends when the plugin is disposed.
      }
    })()
    return () => controller.abort()
  },
}
